fn count_true(arr: &Vec<bool>) -> u64 {
    let mut count: u64 = 0;
    let mut i: usize = 0;
    let n = arr.len();

    // Invariant: 0 <= i <= n, and `count` == number of `true` values in arr[0..i]
    while i < n {
        if arr[i] {
            count += 1;
        }
        i += 1;
    }

    count
}

